+    private async refillWallet(customer?: ReadCustomerResponseData): Promise<string | undefined> {
+        const { balance } = await this.invoicesService.creditService.findCreditBalance({
+            customerId: this.customerId,
+            businessID: this.businessID,
+        });
+        const target = parseFloat(this.topUpAmount);
+        const threshold = parseFloat(this.topUpThreshold) * target;
+        const currentBalance = parseFloat(balance);
+        if (currentBalance >= threshold) {
+            return;
+        }
+        const gap = parseFloat((target - currentBalance).toFixed(2));
+        const items = new InvoiceLineItems();
+        items.addLineItem(new InvoiceLineItem(`${this.offeringName} wallet top-up`, 1, gap));
